            "domain": "3.0",
            "type": "multiple-choice",
            "text": "A Junos device has two routes to 152.41.162.74/24:\n1. A BGP route via 123.8.64.249.\n2. A RIP route via 185.57.93.15.\nAssuming default route preferences, which next-hop will the device use for a packet to 152.41.162.50?",
